import AppKit

/// Menu bar signs: two speech bubbles. Black on transparent, drawn as template images so macOS
/// recolours them for light and dark menu bars. 44 px = 22 pt at 2x.
enum StatusIcons {
    static let idle = make("")
    static let recording = make("")
    static let processing = make("")

    private static func make(_ base64: String) -> NSImage {
        let image = NSImage(data: Data(base64Encoded: base64) ?? Data()) ?? NSImage()
        image.size = NSSize(width: 22, height: 22)
        image.isTemplate = true
        return image
    }
}
